export default function MainPage() {
  useEffect(() => {
    const track = document.getElementById('marqueeTrack');
    if (track) {
      track.innerHTML = '';

      [...logos, ...logos].forEach((logo) => {
        const div = document.createElement('div');
        div.className = 'logo-chip';

        const text = `
      <div class="logo-text">
        <span class="logo-name">${logo.name}</span>
        <span class="logo-subtitle">${logo.subtitle}</span>
      </div>
    `;
        if (logo.type === 'external') {
          div.innerHTML = `
        <img src="${logo.path}" alt="${logo.name}" class="logo-icon" />
        ${text}
      `;
        } else {
          div.innerHTML = `
        <svg viewBox="0 0 64 64" fill="none" class="logo-icon">
          ${logo.path}
        </svg>
        ${text}
      `;
        } track.appendChild(div);
      });
    }

    const grid = document.getElementById('skillGrid');
    if (grid) {
      grid.innerHTML = '';
      skills.forEach((skill) => {
        const item = document.createElement('div');
        item.className = 'skill-item';
        item.innerHTML = `
          <div class="skill-top">
            <span class="skill-name">${skill.name}</span>
            <span class="skill-pct mono">${skill.pct}%</span>
          </div>
          <div class="skill-track">
            <div class="skill-fill" data-pct="${skill.pct}"></div>
          </div>
        `;
        grid.appendChild(item);
      });
    }

    const fills = document.querySelectorAll('.skill-fill');
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.style.width = `${entry.target.dataset.pct}%`;
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.4 }
    );

    fills.forEach((fill) => io.observe(fill));
    fetch('/api/keepalive/', { keepalive: true }).catch(() => {});
  }, []);

  return (
    <>
      <Header />
      <header className="hero">
        <div className="wrap hero-inner">
          <div className="hero-text">
            <div className="eyebrow">shiroharu.eu.org</div>
            <h1>
              Junior Developer.
              <br />
              <span className="grad">Doubling down on JavaScript.</span>
            </h1>
            <p className="lede">
              I'm Shengwei Xiong. Known online as Shiroharu and itsShiroharu. I am a Junior Developer. I'm passionate about creating simple–yet efficient and user-friendly web applications.
            </p>
            <div className="cta-row">
              <a href="#work" className="btn btn-primary">
                View my work →
              </a>
            </div>
          </div>

          <div className="avatar-wrap">
            <div className="avatar-ring" />
            <div className="avatar-frame">
              <img src="/images/profile.webp" alt="Shengwei Xiong" />
            </div>
            <div className="avatar-badge">
              <span />
            </div>
          </div>
        </div>
      </header>

      <section className="powered" id="powered">
        <div className="wrap">
          <div className="section-label">Powered By</div>
        </div>
        <div className="marquee">
          <div className="marquee-track" id="marqueeTrack" />
        </div>
      </section>

      <section className="skills" id="skills">
        <div className="wrap">
          <h2>What I use</h2>
          <p className="sub">These are the tools I used, ranked by my skills and preference.</p>
          <div className="skill-grid" id="skillGrid" />
        </div>
      </section>

      <section className="projects" id="work">
        <div className="wrap">
          <h2>Selected work</h2>
          <p className="sub">A few things I made based on my current skill.</p>
          <div className="project-grid">
            {projects.map((project) => (
              <div className="project-card" key={project.title}>
                <a href={project.link} rel="noopener">
                  <div className="project-top">
                    <div className="project-icon">{project.icon}</div>
                    <span className="project-link">Check Out ↗</span>
                  </div>
                  <h3>{project.title}</h3>
                  <p>{project.description}</p>
                  <div className="tag-row">
                    {project.tags.map((tag) => (
                      <span className="tag" key={tag}>
                        {tag}
                      </span>
                    ))}
                  </div>
                </a>
              </div>
            ))}
          </div>
        </div>
      </section>
      <Footer />
    </>
  );
}

